$jsonContent = "{\n    \"slug\": \"jiri-pacinek\",\n    \"master_name\": \"Ji\u0159\u00ed Pa\u010dinek\",\n    \"og_image\": \"../../uploads/pacinek_master.png\",\n    \"meta_title\": \"U\u010dednictv\u00ed u Ji\u0159\u00edho Pa\u010dinka | Nau\u010d se skl\u00e1\u0159sk\u00e9 \u0159emeslo\",\n    \"meta_desc\": \"Zaj\u00edm\u00e1 t\u011b skl\u00e1\u0159sk\u00e9 \u0159emeslo? Poznej u\u010dednictv\u00ed p\u0159\u00edmo v d\u00edln\u011b Ji\u0159\u00edho Pa\u010dinka v Kunratic\u00edch u Cvikova.\",\n    \"section_order\": [\n        \"hero\",\n        \"uvp\",\n        \"master\",\n        \"outcomes\",\n        \"timeline\",\n        \"portfolio\",\n        \"testimonials\",\n        \"faq\",\n        \"cta\",\n        \"contact\"\n    ],\n    \"design\": {\n        \"color_theme\": \"amber\",\n        \"sticky_cta_enabled\": true,\n        \"sticky_cta_hide_in_hero\": true,\n        \"sticky_cta_hide_in_contact\": true,\n        \"btn_size\": \"m\",\n        \"odd_side_padding\": \"1.2rem\",\n        \"odd_vert_padding\": \"2.8rem\",\n        \"even_side_padding\": \"0.6rem\",\n        \"even_vert_padding\": \"2.2rem\",\n        \"header_show_logo\": true,\n        \"header_show_text\": true,\n        \"header_show_menu\": true\n    },\n    \"typography\": {\n        \"hero_h1\": \"step-3\",\n        \"section_h2\": \"step-3\",\n        \"card_h3\": \"step-3\",\n        \"body_text\": \"step-3\",\n        \"eyebrow\": \"step-3\"\n    },\n    \"hero\": {\n        \"eyebrow\": \"U\u010cEDNICTV\u00cd U MISTRA SKL\u00c1\u0158E\",\n        \"h1\": \"NAU\u010c SE \u0158EMESLO P\u0158\u00cdMO OD MISTRA\",\n        \"subtitle\": \"U\u010dednictv\u00ed u Ji\u0159\u00edho Pa\u010dinka pro mlad\u00e9 lidi (12\u201318 let / mlad\u00e9 dosp\u011bl\u00e9), kte\u0159\u00ed cht\u011bj\u00ed poznat skute\u010dn\u00e9 \u0159emeslo, pracovat rukama a vytvo\u0159it si vlastn\u00ed cestu.\",\n        \"btn_primary\": \"ZJISTIT, JESTLI JE TO PRO M\u011a\",\n        \"btn_secondary\": \"POD\u00cdVAT SE, JAK SE PRACUJE SE SKLEM\",\n        \"image\": \"../../images/sample_master.png\"\n    },\n    \"uvp\": {\n        \"eyebrow\": \"Pro\u010d toto u\u010dednictv\u00ed?\",\n        \"title\": \"SKUTE\u010cN\u00c9 \u0158EMESLO. SKUTE\u010cN\u00dd MISTR. SKUTE\u010cN\u00c1 PR\u00c1CE.\",\n        \"subtitle\": \"Zjisti, pro\u010d je u\u010dednictv\u00ed v huti v\u00fdjime\u010dnou p\u0159\u00edle\u017eitost\u00ed oproti b\u011b\u017en\u00e9 \u0161kole nebo teoretick\u00fdm kurz\u016fm.\",\n        \"items\": [\n            {\n                \"title\": \"Osobn\u00ed veden\u00ed\",\n                \"desc\": \"U\u010dedn\u00edk nen\u00ed anonymn\u00ed student v p\u0159epln\u011bn\u00e9 t\u0159\u00edd\u011b. U\u010d\u00ed\u0161 se p\u0159\u00edmo od Ji\u0159\u00edho a jeho t\u00fdmu v komorn\u00edm prost\u0159ed\u00ed.\"\n            },\n            {\n                \"title\": \"U\u010den\u00ed p\u0159\u00edmo v d\u00edln\u011b\",\n                \"desc\": \"\u017d\u00e1dn\u00e9 hodiny sezen\u00ed nad u\u010debnicemi. Od prvn\u00edho dne pozn\u00e1v\u00e1\u0161 \u017e\u00e1r pece, pr\u00e1ci s p\u00ed\u0161\u0165alou a hork\u00fdm sklem.\"\n            },\n            {\n                \"title\": \"\u0158emeslo od z\u00e1klad\u016f\",\n                \"desc\": \"Postupn\u00fd rozvoj dovednost\u00ed \u2013 od bezpe\u010dnosti a spr\u00e1vn\u00e9ho dr\u017een\u00ed n\u00e1stroj\u016f a\u017e po vlastn\u00ed tvarov\u00e1n\u00ed.\"\n            },\n            {\n                \"title\": \"Kontakt s re\u00e1lnou v\u00fdrobou\",\n                \"desc\": \"Vid\u00ed\u0161, jak vznik\u00e1 profesion\u00e1ln\u00ed zak\u00e1zkov\u00e1 tvorba pro klienty a sb\u011bratele z cel\u00e9ho sv\u011bta.\"\n            },\n            {\n                \"title\": \"Individu\u00e1ln\u00ed p\u0159\u00edstup\",\n                \"desc\": \"Tempo v\u00fduky se p\u0159izp\u016fsobuje tv\u00fdm schopnostem, z\u00e1jmu a fyzick\u00fdm mo\u017enostem.\"\n            },\n            {\n                \"title\": \"Mo\u017enost profesn\u00ed cesty\",\n                \"desc\": \"C\u00edlem nen\u00ed si sklo jen zkusit, ale zjistit, zda se z ru\u010dn\u00edho \u0159emesla m\u016f\u017ee st\u00e1t tvoje budoucnost.\"\n            }\n        ]\n    },\n    \"master\": {\n        \"eyebrow\": \"KDO T\u011a BUDE U\u010cIT\",\n        \"name\": \"JI\u0158\u00cd PA\u010cINEK\",\n        \"title\": \"Um\u011bleck\u00fd skl\u00e1\u0159 a mistr \u0159emesla \u2022 Skl\u00e1rna Kunratice u Cvikova\",\n        \"bio\": \"Ji\u0159\u00ed Pa\u010dinek vybudoval rodinnou skl\u00e1rnu Pa\u010dinek Glass a unik\u00e1tn\u00ed K\u0159i\u0161\u0165\u00e1lovou zahradu v Kunratic\u00edch u Cvikova. Jeho ru\u010dn\u011b tvarovan\u00e9 objekty, plastiky a sv\u00edtidla obdivuj\u00ed sb\u011bratel\u00e9 po cel\u00e9m sv\u011bt\u011b.\",\n        \"quote\": \"\u201e\u0158emeslo nen\u00ed jen pr\u00e1ce s materi\u00e1lem. Je to pokora, soust\u0159ed\u011bn\u00ed a schopnost vtisknout \u017ehav\u00e9 hmot\u011b tvar i my\u0161lenku.\u201c\",\n        \"bio2\": \"V d\u00edln\u011b s\u00e1z\u00ed na poctiv\u00fd p\u0159\u00edstup, t\u00fdmovou spolupr\u00e1ci u pece a p\u0159ed\u00e1v\u00e1n\u00ed skl\u00e1\u0159sk\u00e9ho um\u011bn\u00ed dal\u0161\u00ed generaci.\",\n        \"image\": \"../../images/sample_master.png\"\n    },\n    \"outcomes\": {\n        \"eyebrow\": \"Praktick\u00e9 dovednosti\",\n        \"title\": \"CO SE U\u010cEDN\u00cdK SKUTE\u010cN\u011a NAU\u010c\u00cd\",\n        \"subtitle\": \"Konkr\u00e9tn\u00ed znalosti a n\u00e1vyky, kter\u00e9 si z d\u00edlny odnese\u0161 do \u017eivota.\",\n        \"items\": [\n            {\n                \"icon\": \"\ud83d\udd25\",\n                \"title\": \"Pr\u00e1ce s n\u00e1stroji\",\n                \"desc\": \"Pozn\u00e1\u0161 skl\u00e1\u0159skou p\u00ed\u0161\u0165alu, n\u016f\u017eky, sval\u00e1ky i kle\u0161t\u011b a nau\u010d\u00ed\u0161 se s nimi bezpe\u010dn\u011b manipulovat.\"\n            },\n            {\n                \"icon\": \"\ud83e\uddea\",\n                \"title\": \"Pr\u00e1ce se sklem\",\n                \"desc\": \"Pochop\u00ed\u0161 chov\u00e1n\u00ed roztaven\u00e9ho materi\u00e1lu p\u0159i teplot\u00e1ch p\u0159es 1100 \u00b0C a jeho chladnut\u00ed.\"\n            },\n            {\n                \"icon\": \"\ud83c\udfa8\",\n                \"title\": \"Tvarov\u00e1n\u00ed & Barvy\",\n                \"desc\": \"Osvoj\u00ed\u0161 si z\u00e1klady fouk\u00e1n\u00ed, nav\u00edjen\u00ed barvy a formov\u00e1n\u00ed tvar\u016f u s\u00e1zec\u00ed pece.\"\n            },\n            {\n                \"icon\": \"\ud83c\udfed\",\n                \"title\": \"Pr\u00e1ce v huti\",\n                \"desc\": \"Za\u017eije\u0161 re\u00e1ln\u00fd rytmus t\u00fdmu na skl\u00e1\u0159sk\u00e9 huti a komunikaci p\u0159i spole\u010dn\u00e9m d\u00edle.\"\n            },\n            {\n                \"icon\": \"\ud83d\udee1\ufe0f\",\n                \"title\": \"Bezpe\u010dnost & N\u00e1vyky\",\n                \"desc\": \"Z\u00edsk\u00e1\u0161 respekt k hork\u00e9mu prost\u0159ed\u00ed a nau\u010d\u00ed\u0161 se p\u0159\u00edsn\u00fdm pravidl\u016fm ochrany zdrav\u00ed.\"\n            },\n            {\n                \"icon\": \"\ud83d\udcaa\",\n                \"title\": \"Samostatnost & Trp\u011blivost\",\n                \"desc\": \"Rozvine\u0161 soust\u0159ed\u011bn\u00ed, vytrvalost a schopnost u\u010dit se z vlastn\u00edch chyb.\"\n            }\n        ]\n    },\n    \"timeline\": {\n        \"eyebrow\": \"Postup krok za krokem\",\n        \"title\": \"JAK PROB\u00cdH\u00c1 CESTA K U\u010cEDNICTV\u00cd\",\n        \"subtitle\": \"P\u011bt jasn\u00fdch krok\u016f od prvn\u00edho projeven\u00ed z\u00e1jmu a\u017e po za\u010d\u00e1tek pr\u00e1ce v d\u00edln\u011b.\",\n        \"steps\": [\n            {\n                \"num\": \"01\",\n                \"title\": \"PRVN\u00cd ROZHOVOR\",\n                \"desc\": \"Nez\u00e1vazn\u00fd rozhovor se z\u00e1stupcem Svobodn\u00fdch cech\u016f (telefon/WhatsApp), kde zjist\u00edme tv\u00e1 o\u010dek\u00e1v\u00e1n\u00ed a zodpov\u00edme prvn\u00ed dotazy.\"\n            },\n            {\n                \"num\": \"02\",\n                \"title\": \"SETK\u00c1N\u00cd S MISTREM\",\n                \"desc\": \"Nav\u0161t\u00edv\u00ed\u0161 skl\u00e1rnu Pa\u010dinek Glass v Kunratic\u00edch u Cvikova, potk\u00e1\u0161 se s Ji\u0159\u00edm Pa\u010dinkem a prohl\u00e9dne\u0161 si hu\u0165.\"\n            },\n            {\n                \"num\": \"03\",\n                \"title\": \"ZKU\u0160EBN\u00cd DEN\",\n                \"desc\": \"Vyzkou\u0161\u00ed\u0161 si re\u00e1ln\u00fd den v d\u00edln\u011b. Ob\u011b strany si ov\u011b\u0159\u00ed, zda jim vz\u00e1jemn\u00e1 spolupr\u00e1ce a atmosf\u00e9ra vyhovuje.\"\n            },\n            {\n                \"num\": \"04\",\n                \"title\": \"DOMLUV\u00cdME SE\",\n                \"desc\": \"Spole\u010dn\u011b dohodneme konkr\u00e9tn\u00ed podm\u00ednky, \u010dasov\u00fd rozvrh, v\u011bkov\u00e9 a praktick\u00e9 mo\u017enosti (v\u010detn\u011b p\u0159\u00edpadn\u00e9ho ubytov\u00e1n\u00ed/strava).\"\n            },\n            {\n                \"num\": \"05\",\n                \"title\": \"ZA\u010c\u00cdN\u00c1 U\u010cEDNICTV\u00cd\",\n                \"desc\": \"Teprve po oboustrann\u00e9 dohod\u011b za\u010d\u00edn\u00e1 tvoje pravideln\u00e1 \u0159emesln\u00e1 cesta p\u0159\u00edmo u skl\u00e1\u0159sk\u00e9 pece.\"\n            }\n        ],\n        \"disclaimer\": \"\ud83d\udca1 Z\u00e1kladn\u00ed cesta vypad\u00e1 takto. Konkr\u00e9tn\u00ed pr\u016fb\u011bh se v\u017edy p\u0159izp\u016fsobuje \u010dlov\u011bku, jeho \u010dasov\u00fdm mo\u017enostem a zku\u0161enostem.\"\n    },\n    \"portfolio\": {\n        \"eyebrow\": \"Uk\u00e1zka z prost\u0159ed\u00ed\",\n        \"title\": \"CO VZNIK\u00c1 V D\u00cdLN\u011a\",\n        \"subtitle\": \"Nahl\u00e9dni do \u017eiv\u00e9ho procesu skl\u00e1\u0159sk\u00e9ho um\u011bn\u00ed \u2013 od materi\u00e1lu po hotov\u00e9 d\u00edlo.\",\n        \"items\": [\n            {\n                \"image\": \"../../images/sample_master.png\",\n                \"caption\": \"\u017dhav\u00e1 sklovina u s\u00e1zec\u00ed pece\"\n            },\n            {\n                \"image\": \"../../images/sample_master.png\",\n                \"caption\": \"Tvarov\u00e1n\u00ed na skl\u00e1\u0159sk\u00e9 lavici\"\n            },\n            {\n                \"image\": \"../../images/sample_master.png\",\n                \"caption\": \"Detail hutn\u011b tvarovan\u00e9 sklen\u011bn\u00e9 plastiky\"\n            },\n            {\n                \"image\": \"../../images/sample_master.png\",\n                \"caption\": \"K\u0159i\u0161\u0165\u00e1lov\u00e1 zahrada v Kunratic\u00edch\"\n            }\n        ]\n    },\n    \"testimonials\": {\n        \"eyebrow\": \"Zku\u0161enosti a reference\",\n        \"title\": \"CO \u0158\u00cdKAJ\u00cd LID\u00c9, KTE\u0158\u00cd U TOHO BYLI\",\n        \"subtitle\": \"Re\u00e1ln\u00e9 pohledy z\u00e1stupc\u016f, rodin a spolupracovn\u00edk\u016f.\",\n        \"items\": [\n            {\n                \"quote\": \"\u201eSkl\u00e1\u0159stv\u00ed je tvrd\u00e1 pr\u00e1ce, ale vid\u011bt syna, jak pod veden\u00edm Ji\u0159\u00edho z\u00edsk\u00e1v\u00e1 jistotu a respekt k materi\u00e1lu, je neuv\u011b\u0159iteln\u00e9.\u201c\",\n                \"name\": \"Petr M.\",\n                \"role\": \"Rodi\u010d z\u00e1jemce o \u0159emeslo\"\n            },\n            {\n                \"quote\": \"\u201eMo\u017enost stoupnout si k peci v Kunratic\u00edch a sledovat mistra Pa\u010dinka p\u0159i pr\u00e1ci mi otev\u0159ela o\u010di. \u0158emeslo m\u00e1 obrovskou budoucnost.\u201c\",\n                \"name\": \"Martin K.\",\n                \"role\": \"\u00da\u010dastn\u00edk zku\u0161ebn\u00edho dne\"\n            },\n            {\n                \"quote\": \"\u201eSpolupr\u00e1ce se Svobodn\u00fdmi Cechy pom\u00e1h\u00e1 p\u0159iv\u00e9st k poctiv\u00fdm \u0159emesl\u016fm mlad\u00e9 lidi, kte\u0159\u00ed maj\u00ed chu\u0165 n\u011bco vytvo\u0159it vlastn\u00edma rukama.\u201c\",\n                \"name\": \"T\u00fdm Pa\u010dinek Glass\",\n                \"role\": \"Kunratice u Cvikova\"\n            }\n        ]\n    },\n    \"faq\": {\n        \"eyebrow\": \"Odpov\u011bdi na dotazy\",\n        \"title\": \"\u010cAST\u00c9 OT\u00c1ZKY\",\n        \"subtitle\": \"V\u0161e, co t\u011b (nebo tvoje rodi\u010de) m\u016f\u017ee zaj\u00edmat p\u0159ed prvn\u00edm kontaktem.\",\n        \"items\": [\n            {\n                \"q\": \"Pro koho je u\u010dednictv\u00ed ur\u010deno?\",\n                \"a\": \"Prvo\u0159ad\u011b pro mlad\u00e9 lidi ve v\u011bku cca 12\u201318 let a mlad\u00e9 dosp\u011bl\u00e9, kte\u0159\u00ed maj\u00ed z\u00e1jem o ru\u010dn\u00ed \u0159emeslo, sklo a praktickou tvorbu.\"\n            },\n            {\n                \"q\": \"Mus\u00edm m\u00edt p\u0159edchoz\u00ed zku\u0161enosti se sklem?\",\n                \"a\": \"Nen\u00ed to nutn\u00e9! V\u0161echny z\u00e1klady bezpe\u010dnosti, manipulace s n\u00e1\u0159ad\u00edm i pr\u00e1ce s materi\u00e1lem t\u011b nau\u010d\u00edme p\u0159\u00edmo v d\u00edln\u011b.\"\n            },\n            {\n                \"q\": \"Jak prob\u00edh\u00e1 zku\u0161ebn\u00ed den?\",\n                \"a\": \"B\u011bhem zku\u0161ebn\u00edho dne se sezn\u00e1m\u00ed\u0161 s chodem huti, vyzkou\u0161\u00ed\u0161 si z\u00e1kladn\u00ed \u00fakony a zjist\u00ed\u0161, zda ti atmosf\u00e9ra v d\u00edln\u011b sed\u00ed.\"\n            },\n            {\n                \"q\": \"Kde p\u0159esn\u011b se u\u010dednictv\u00ed kon\u00e1?\",\n                \"a\": \"U\u010dednictv\u00ed prob\u00edh\u00e1 p\u0159\u00edmo v are\u00e1lu skl\u00e1rny Pa\u010dinek Glass v Kunratic\u00edch u Cvikova (Libereck\u00fd kraj).\"\n            },\n            {\n                \"q\": \"Je mo\u017en\u00e9 domluvit ubytov\u00e1n\u00ed, pokud jsem zdaleka?\",\n                \"a\": \"Mo\u017enosti ubytov\u00e1n\u00ed a dopravy \u0159e\u0161\u00edme individu\u00e1ln\u011b p\u0159i osobn\u00edm rozhovoru podle konkr\u00e9tn\u00edch pot\u0159eb u\u010dedn\u00edka.\"\n            },\n            {\n                \"q\": \"Mus\u00edm se hned k ne\u010demu zav\u00e1zat?\",\n                \"a\": \"V\u016fbec ne. Prvn\u00edm krokem je zcela nez\u00e1vazn\u00fd rozhovor, kde si vyjasn\u00edme dotazy a p\u0159edstav\u00edme mo\u017enosti.\"\n            }\n        ]\n    },\n    \"cta\": {\n        \"title\": \"ZAJ\u00cdM\u00c1 T\u011a, JESTLI JE TO PRO TEBE?\",\n        \"text\": \"Nemus\u00ed\u0161 se hned k ni\u010demu zavazovat. Prvn\u00ed krok je jednoduch\u00fd nez\u00e1vazn\u00fd rozhovor, kde spole\u010dn\u011b probereme, co hled\u00e1\u0161 a jestli by ti u\u010dednictv\u00ed vyhovovalo.\",\n        \"btn\": \"ZJISTIT, JESTLI JE TO PRO M\u011a\"\n    },\n    \"contact\": {\n        \"eyebrow\": \"Prvn\u00ed krok\",\n        \"title\": \"NAV\u00c1\u017dEME KONTAKT\",\n        \"subtitle\": \"Zvol si zp\u016fsob, kter\u00fd je pro t\u011b nejsnadn\u011bj\u0161\u00ed.\",\n        \"whatsapp_num\": \"420602763599\",\n        \"whatsapp_msg\": \"Dobr\u00fd den, cht\u011bl/a bych zjistit, jestli je u\u010dednictv\u00ed u Ji\u0159\u00edho Pa\u010dinka pro m\u011b.\",\n        \"instagram_link\": \"https://instagram.com\",\n        \"phone_parent\": \"+420 602 763 599\"\n    }\n}";
$htmlContent = "<!DOCTYPE html>\n<html lang=\"cs\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <script>if (location.protocol !== 'https:' && location.hostname !== 'localhost' && location.hostname !== '127.0.0.1') { location.replace('https://' + location.hostname + location.pathname + location.search + location.hash); }</script>\n  <meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\" />\n  <meta http-equiv=\"Pragma\" content=\"no-cache\" />\n  <meta http-equiv=\"Expires\" content=\"0\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>U\u010dednictv\u00ed u Ji\u0159\u00edho Pa\u010dinka | Nau\u010d se skl\u00e1\u0159sk\u00e9 \u0159emeslo \u2013 Svobodn\u00e9 Cechy</title>\n  <meta name=\"description\" content=\"Zaj\u00edm\u00e1 t\u011b skl\u00e1\u0159sk\u00e9 \u0159emeslo? Poznej u\u010dednictv\u00ed p\u0159\u00edmo v d\u00edln\u011b Ji\u0159\u00edho Pa\u010dinka v Kunratic\u00edch u Cvikova. Zjisti, jak u\u010dednictv\u00ed prob\u00edh\u00e1 a jestli je pro tebe.\" />\n\n  <!-- Open Graph / Facebook / WhatsApp / LinkedIn -->\n  <meta property=\"og:type\" content=\"website\" />\n  <meta property=\"og:url\" content=\"https://beta.svobodnecechy.cz/admin/landing_pages/jiri-pacinek.html\" />\n  <meta property=\"og:title\" content=\"U\u010dednictv\u00ed u Ji\u0159\u00edho Pa\u010dinka | Nau\u010d se skl\u00e1\u0159sk\u00e9 \u0159emeslo \u2013 Svobodn\u00e9 Cechy\" />\n  <meta property=\"og:description\" content=\"Zaj\u00edm\u00e1 t\u011b skl\u00e1\u0159sk\u00e9 \u0159emeslo? Poznej u\u010dednictv\u00ed p\u0159\u00edmo v d\u00edln\u011b Ji\u0159\u00edho Pa\u010dinka v Kunratic\u00edch u Cvikova. Zjisti, jak u\u010dednictv\u00ed prob\u00edh\u00e1 a jestli je pro tebe.\" />\n  <meta property=\"og:image\" content=\"https://beta.svobodnecechy.cz/uploads/pacinek_master.png\" />\n  <meta property=\"og:image:alt\" content=\"U\u010dednictv\u00ed u Ji\u0159\u00edho Pa\u010dinka | Nau\u010d se skl\u00e1\u0159sk\u00e9 \u0159emeslo \u2013 Svobodn\u00e9 Cechy\" />\n\n  <!-- Twitter Card -->\n  <meta name=\"twitter:card\" content=\"summary_large_image\" />\n  <meta name=\"twitter:url\" content=\"https://beta.svobodnecechy.cz/admin/landing_pages/jiri-pacinek.html\" />\n  <meta name=\"twitter:title\" content=\"U\u010dednictv\u00ed u Ji\u0159\u00edho Pa\u010dinka | Nau\u010d se skl\u00e1\u0159sk\u00e9 \u0159emeslo \u2013 Svobodn\u00e9 Cechy\" />\n  <meta name=\"twitter:description\" content=\"Zaj\u00edm\u00e1 t\u011b skl\u00e1\u0159sk\u00e9 \u0159emeslo? Poznej u\u010dednictv\u00ed p\u0159\u00edmo v d\u00edln\u011b Ji\u0159\u00edho Pa\u010dinka v Kunratic\u00edch u Cvikova. Zjisti, jak u\u010dednictv\u00ed prob\u00edh\u00e1 a jestli je pro tebe.\" />\n  <meta name=\"twitter:image\" content=\"https://beta.svobodnecechy.cz/uploads/pacinek_master.png\" />\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,600;0,700;1,600&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />\n  <style>\n    :root {\n      --color-primary: #0B0A08;\n      --color-dark: #17120E;\n      --color-cream: #F4EFE7;\n      --color-white: #FFFDF8;\n      --color-accent: #E87516;\n      --color-glass: rgba(255, 255, 255, 0.05);\n      --color-glass-border: rgba(255, 255, 255, 0.1);\n      --text: #F4EFE7;\n      --text-muted: #A39B8E;\n      --font-heading: 'Cormorant Garamond', serif;\n      --font-body: 'Inter', sans-serif;\n\n      /* Configured Fluid Typography Steps */\n      --hero-h1-clamp: clamp(2.0rem, 5vw, 3.4rem);\n      --section-h2-clamp: clamp(1.7rem, 4vw, 2.6rem);\n      --card-h3-clamp: clamp(1.25rem, 2.5vw, 1.5rem);\n      --body-text-size: 1.05rem;\n      --eyebrow-size: 0.85rem;\n\n      /* Button size configuration (Desktop & Mobile) */\n      --btn-pad-v: 0.9rem;\n      --btn-pad-h: 1.8rem;\n      --btn-font-size: 1.05rem;\n      --btn-pad-v-mob: 0.6rem;\n      --btn-pad-h-mob: 1.2rem;\n      --btn-font-size-mob: 0.85rem;\n    }\n\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    html { scroll-behavior: smooth; }\n    body {\n      font-family: var(--font-body);\n      background: linear-gradient(135deg, var(--color-primary), var(--color-dark));\n      color: var(--text);\n      line-height: 1.5;\n      font-size: var(--body-text-size);\n    }\n\n    .container { max-width: 1200px; margin: auto; padding: 0 1.5rem; }\n\n    /* Sticky Header */\n    .site-header {\n      position: sticky;\n      top: 0;\n      background: rgba(11, 10, 8, 0.92);\n      backdrop-filter: blur(10px);\n      z-index: 100;\n      border-bottom: 1px solid rgba(232, 117, 22, 0.2);\n    }\n    .nav-container {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 1rem 1.5rem;\n      max-width: 1280px;\n      margin: auto;\n    }\n    .logo {\n      font-family: var(--font-heading);\n      font-size: 1.6rem;\n      font-weight: 700;\n      color: var(--color-accent);\n      text-decoration: none;\n      letter-spacing: 1px;\n    }\n    .nav-menu { list-style: none; display: flex; gap: 1.5rem; align-items: center; }\n    .nav-menu a { color: var(--text); text-decoration: none; font-size: 0.95rem; font-weight: 600; transition: color .2s; }\n    .nav-menu a:hover { color: var(--color-accent); }\n    .cta-nav {\n      background: var(--color-accent);\n      color: #fff !important;\n      padding: 0.6rem 1.2rem;\n      border-radius: 6px;\n      font-weight: 700;\n      transition: transform .2s, background .2s;\n    }\n    .cta-nav:hover { background: #d0640d; transform: scale(1.03); }\n\n    /* Unified heading typography \u2014 tight line-height prevents large gaps on line breaks */\n    h1, h2, h3, h4 {\n      line-height: 1.15;\n      letter-spacing: -0.02em;\n      overflow-wrap: break-word;\n      word-break: break-word;\n      margin-bottom: 0.5rem;\n    }\n\n    .hero-wrapper { padding-bottom: 2.5rem; }\n    .hero { display: grid; grid-template-columns: 1fr 1fr; align-items: center; gap: 2.5rem; padding: 3.5rem 0 1.5rem; min-height: 55vh; }\n    .hero-content { max-width: 580px; }\n    .eyebrow {\n      text-transform: uppercase;\n      font-size: var(--eyebrow-size);\n      letter-spacing: 2px;\n      color: var(--color-accent);\n      font-weight: 700;\n      margin-bottom: 0.6rem;\n    }\n    .hero h1 {\n      font-family: var(--font-heading);\n      font-size: var(--hero-h1-clamp);\n      color: var(--color-white);\n      margin-bottom: 0.8rem;\n    }\n    .subtitle { font-size: clamp(0.95rem, 2vw, 1.1rem); color: var(--text-muted); margin-bottom: 0; line-height: 1.5; }\n    .hero-buttons-row { display: flex; gap: 1rem; flex-wrap: wrap; justify-content: center; align-items: center; padding-top: 1.8rem; width: 100%; text-align: center; }\n    .hero-buttons { display: flex; gap: 1rem; flex-wrap: wrap; justify-content: center; align-items: center; text-align: center; }\n    .btn {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      padding: 0.9rem 1.8rem;\n      font-size: 1.05rem;\n      border-radius: 6px;\n      font-weight: 700;\n      text-decoration: none;\n      transition: all .2s;\n      min-height: 42px;\n      cursor: pointer;\n      border: none;\n      text-align: center;\n    }\n    @media (max-width: 768px) {\n      .btn {\n        padding: 0.6rem 1.2rem !important;\n        font-size: 0.85rem !important;\n      }\n    }\n    .btn-primary { background: var(--color-accent); color: #fff; }\n    .btn-primary:hover { background: #d0640d; transform: translateY(-2px); box-shadow: 0 8px 20px rgba(232, 117, 22, 0.3); }\n    .btn-secondary { background: var(--color-glass); color: var(--text); border: 1px solid var(--color-accent); }\n    .btn-secondary:hover { background: rgba(232, 117, 22, 0.15); transform: translateY(-2px); }\n    .section-cta-wrap { display: flex; justify-content: center; align-items: center; text-align: center; margin-top: 2.5rem; padding-top: 0.5rem; width: 100%; }\n    .hero-image img {\n      width: 100%;\n      max-height: 400px;\n      object-fit: cover;\n      border-radius: 12px;\n      box-shadow: 0 10px 30px rgba(0,0,0,0.6);\n      border: 1px solid var(--color-glass-border);\n    }\n\n    /* Section title nadpisy */\n    .section-title { text-align: center; margin-bottom: 2.5rem; }\n    .section-title h2 {\n      font-family: var(--font-heading);\n      font-size: var(--section-h2-clamp);\n      color: var(--color-white);\n      margin-bottom: 0.5rem;\n    }\n    .section-title p { color: var(--text-muted); font-size: clamp(0.95rem, 2vw, 1.1rem); max-width: 680px; margin: auto; }\n\n    /* UVP Grid */\n    .uvp-section { padding: 3.5rem 0; }\n    .uvp-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 1.2rem; }\n    .uvp-card {\n      background: var(--color-glass);\n      border: 1px solid var(--color-glass-border);\n      border-radius: 12px;\n      padding: 1.5rem;\n      transition: border-color .3s;\n    }\n    .uvp-card:hover { border-color: var(--color-accent); }\n    .uvp-card h3 { font-family: var(--font-heading); font-size: var(--card-h3-clamp); color: var(--color-accent); margin-bottom: 0.4rem; }\n\n    /* Master Section */\n    .master-section { padding: 5rem 0; background: rgba(0,0,0,0.3); border-y: 1px solid var(--color-glass-border); }\n    .master-grid { display: grid; grid-template-columns: 1fr 1.3fr; gap: 3.5rem; align-items: center; }\n    .master-photo img { width: 100%; border-radius: 14px; border: 1px solid var(--color-accent); }\n    .master-info h3 { font-family: var(--font-heading); font-size: var(--hero-h1-clamp); color: var(--color-white); margin-bottom: 0.5rem; }\n    .master-title { color: var(--color-accent); font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 1.5rem; font-size: var(--eyebrow-size); }\n    .quote-box {\n      font-family: var(--font-heading);\n      font-style: italic;\n      font-size: clamp(1.1rem, 2.2vw, 1.35rem);\n      color: var(--color-cream);\n      border-left: 3px solid var(--color-accent);\n      padding-left: 1.2rem;\n      margin: 1.5rem 0;\n    }\n\n    /* Learning Outcomes */\n    .outcomes-section { padding: 5rem 0; }\n    .outcomes-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1.8rem; }\n    .outcome-item {\n      background: var(--color-glass);\n      border: 1px solid var(--color-glass-border);\n      border-radius: 12px;\n      padding: 1.8rem;\n    }\n    .outcome-item h4 { font-family: var(--font-heading); font-size: clamp(1.1rem, 2.2vw, 1.4rem); color: var(--color-white); margin-bottom: 0.4rem; }\n\n    /* How It Works Timeline */\n    .timeline-section { padding: 5rem 0; background: rgba(0,0,0,0.2); }\n    .timeline { display: flex; flex-direction: column; gap: 1.5rem; max-width: 900px; margin: auto; }\n    .timeline-step {\n      display: grid;\n      grid-template-columns: 80px 1fr;\n      gap: 1.5rem;\n      background: var(--color-glass);\n      border: 1px solid var(--color-glass-border);\n      border-left: 4px solid var(--color-accent);\n      border-radius: 8px;\n      padding: 1.5rem;\n      align-items: center;\n    }\n    .step-number { font-family: var(--font-heading); font-size: clamp(1.6rem, 3vw, 2.2rem); font-weight: 700; color: var(--color-accent); text-align: center; }\n    .step-content h4 { font-family: var(--font-heading); font-size: clamp(1.1rem, 2.2vw, 1.4rem); color: var(--color-white); margin-bottom: 0.3rem; }\n    .disclaimer-box { text-align: center; font-size: 0.95rem; color: var(--text-muted); margin-top: 2rem; font-style: italic; }\n\n    /* Portfolio Gallery */\n    .portfolio-section { padding: 5rem 0; }\n    .portfolio-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }\n    .portfolio-item { position: relative; border-radius: 10px; overflow: hidden; border: 1px solid var(--color-glass-border); }\n    .portfolio-item img { width: 100%; height: 260px; object-fit: cover; display: block; transition: transform .4s; }\n    .portfolio-item:hover img { transform: scale(1.05); }\n    .portfolio-caption {\n      position: absolute; bottom: 0; left: 0; right: 0;\n      background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);\n      padding: 1.2rem 1rem 0.8rem; color: var(--color-white); font-weight: 600; font-size: 0.95rem;\n    }\n\n    /* Social Proof */\n    .testimonials-section { padding: 5rem 0; background: rgba(0,0,0,0.3); }\n    .testimonials-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1.8rem; }\n    .testimonial-card {\n      background: var(--color-glass);\n      border: 1px solid var(--color-glass-border);\n      border-radius: 12px;\n      padding: 2rem;\n    }\n    .quote-text { font-style: italic; margin-bottom: 1.2rem; color: var(--color-cream); }\n    .author-info { display: flex; align-items: center; gap: 1rem; }\n    .author-info strong { color: var(--color-accent); display: block; font-size: 1rem; }\n    .author-info span { font-size: 0.85rem; color: var(--text-muted); }\n\n    /* FAQ Section */\n    .faq-section { padding: 5rem 0; }\n    .faq-list { max-width: 850px; margin: auto; display: flex; flex-direction: column; gap: 1rem; }\n    details {\n      background: var(--color-glass);\n      border: 1px solid var(--color-glass-border);\n      border-radius: 8px;\n      padding: 1.2rem 1.5rem;\n      transition: background .2s;\n    }\n    details[open] { border-color: var(--color-accent); background: rgba(232, 117, 22, 0.05); }\n    summary {\n      font-family: var(--font-heading);\n      font-size: clamp(1.1rem, 2.2vw, 1.4rem);\n      font-weight: 600;\n      color: var(--color-white);\n      cursor: pointer;\n      outline: none;\n      list-style: none;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n    summary::-webkit-details-marker { display: none; }\n    summary::after { content: '+'; font-size: 1.6rem; color: var(--color-accent); }\n    details[open] summary::after { content: '\u2212'; }\n    details p { margin-top: 1rem; color: var(--text-muted); font-size: 1rem; }\n\n    /* Primary CTA Box */\n    .primary-cta-box {\n      background: linear-gradient(135deg, rgba(232,117,22,0.15), rgba(17,14,11,0.9));\n      border: 2px solid var(--color-accent);\n      border-radius: 16px;\n      padding: 4rem 2rem;\n      text-align: center;\n      margin: 4rem auto;\n      max-width: 900px;\n    }\n    .primary-cta-box h2 { font-family: var(--font-heading); font-size: clamp(1.6rem, 3.5vw, 2.4rem); color: var(--color-white); margin-bottom: 1rem; }\n    .primary-cta-box p { color: var(--text-muted); font-size: clamp(0.95rem, 2vw, 1.1rem); max-width: 650px; margin: 0 auto 2rem; }\n\n    /* Contact Section */\n    .contact-section { padding: 4rem 0 6rem; }\n    .contact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: start; }\n    .contact-card {\n      background: var(--color-glass);\n      border: 1px solid var(--color-glass-border);\n      border-radius: 14px;\n      padding: 2.5rem;\n    }\n    .contact-card h3 { font-family: var(--font-heading); font-size: clamp(1.3rem, 2.8vw, 1.8rem); color: var(--color-white); margin-bottom: 1rem; }\n    .contact-options { display: flex; flex-direction: column; gap: 1rem; margin-top: 1.5rem; }\n    .btn-wa { background: #25D366; color: #fff; text-decoration: none; font-weight: 700; border-radius: 6px; padding: 1rem; text-align: center; display: inline-flex; align-items: center; justify-content: center; gap: 0.6rem; }\n    .btn-wa:hover { background: #1eb956; }\n    .btn-ig { background: linear-gradient(45deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%); color: #fff; text-decoration: none; font-weight: 700; border-radius: 6px; padding: 1rem; text-align: center; display: inline-flex; align-items: center; justify-content: center; gap: 0.6rem; }\n\n    /* Parent Toggle & Form */\n    .parent-box { margin-top: 2rem; padding-top: 2rem; border-top: 1px solid var(--color-glass-border); }\n    .form-group { margin-bottom: 1.2rem; }\n    .form-group label { display: block; font-size: 0.9rem; font-weight: 600; color: var(--text-muted); margin-bottom: 0.4rem; }\n    .form-control { width: 100%; padding: 0.8rem 1rem; background: rgba(0,0,0,0.5); border: 1px solid var(--color-glass-border); border-radius: 6px; color: #fff; font-size: 1rem; }\n    .form-control:focus { outline: none; border-color: var(--color-accent); }\n\n    /* Floating Sticky CTA (PC, Tablet & Mobile) */\n    .mobile-sticky-cta {\n      display: block;\n      position: fixed;\n      bottom: 1.2rem;\n      left: 50%;\n      transform: translateX(-50%);\n      width: calc(100% - 2rem);\n      max-width: 500px;\n      background: rgba(17, 14, 11, 0.94);\n      backdrop-filter: blur(12px);\n      -webkit-backdrop-filter: blur(12px);\n      border: 1px solid var(--color-accent);\n      border-radius: 50px;\n      padding: 0.5rem 0.6rem;\n      z-index: 999;\n      box-shadow: 0 12px 35px rgba(0, 0, 0, 0.7), 0 0 15px rgba(232, 117, 22, 0.25);\n      text-align: center;\n      transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n    .mobile-sticky-cta .btn {\n      width: 100%;\n      border-radius: 40px;\n      box-shadow: 0 4px 15px rgba(232, 117, 22, 0.4);\n    }\n\n    /* Footer */\n    footer { border-top: 1px solid var(--color-glass-border); padding: 3rem 0; text-align: center; color: var(--text-muted); font-size: 0.9rem; }\n\n    /* Responsive */\n    @media (max-width: 900px) {\n      .hero { grid-template-columns: 1fr; text-align: center; gap: 1.5rem; min-height: auto; }\n      .hero-content { max-width: 100%; }\n      .hero-buttons-row { justify-content: center; padding-top: 1.2rem; }\n      .hero-buttons { justify-content: center; }\n      .master-grid { grid-template-columns: 1fr; }\n      .contact-grid { grid-template-columns: 1fr; }\n      .nav-container { flex-wrap: wrap; justify-content: center; gap: 0.8rem; }\n      .nav-menu { gap: 0.7rem 1rem; flex-wrap: wrap; justify-content: center; font-size: 0.82rem; }\n      .nav-menu a { font-size: 0.82rem; }\n      .cta-nav { padding: 0.35rem 0.75rem; font-size: 0.78rem; }\n      .hero h1 { font-size: 2.6rem; }\n    }\n    @media (max-width: 600px) {\n      .nav-container { flex-direction: column; text-align: center; gap: 0.6rem; }\n      .nav-menu { gap: 0.5rem 0.8rem; justify-content: center; }\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Sticky Header -->\n  <header class=\"site-header\" id=\"site-header\">\n    <div class=\"nav-container\">\n      <a href=\"#\" class=\"logo\" style=\"display:inline-flex; align-items:center; gap:0.6rem;\"><img src=\"../../LOGO_SC2.svg\" alt=\"Svobodn\u00e9 Cechy\" style=\"height:34px; width:auto; vertical-align:middle; display:block;\" /><span>SVOBODN\u00c9 CECHY</span></a>\n      <ul class=\"nav-menu\" id=\"header-nav-menu\">\n        <li><a href=\"#uvp\">Pro\u010d?</a></li>\n        <li><a href=\"#mistr\">O mistrovi</a></li>\n        <li><a href=\"#co-se-naucis\">Co se nau\u010d\u00ed\u0161</a></li>\n        <li><a href=\"#jak-to-probiha\">Jak to prob\u00edh\u00e1</a></li>\n        <li><a href=\"#realizace\">Realizace</a></li>\n        <li><a href=\"#reference\">Reference</a></li>\n        <li><a href=\"#faq\">FAQ</a></li>\n        <li><a href=\"#kontakt\" class=\"cta-nav\">ZJISTIT, JESTLI JE TO PRO M\u011a</a></li>\n      </ul>\n    </div>\n  </header>\n\n  <main>\n    <!-- Section 1: Hero -->\n    <section class=\"hero-wrapper\">\n      <div class=\"container hero\">\n        <div class=\"hero-content\">\n          <p class=\"eyebrow\">U\u010cEDNICTV\u00cd U MISTRA SKL\u00c1\u0158E</p>\n          <h1>NAU\u010c SE \u0158EMESLO P\u0158\u00cdMO OD MISTRA</h1>\n          <p class=\"subtitle\">U\u010dednictv\u00ed u Ji\u0159\u00edho Pa\u010dinka pro mlad\u00e9 lidi (12\u201318 let / mlad\u00e9 dosp\u011bl\u00e9), kte\u0159\u00ed cht\u011bj\u00ed poznat skute\u010dn\u00e9 \u0159emeslo, pracovat rukama a vytvo\u0159it si vlastn\u00ed cestu.</p>\n        </div>\n        <div class=\"hero-image\">\n          <img src=\"../../images/sample_master.png\" alt=\"Ji\u0159\u00ed Pa\u010dinek p\u0159i pr\u00e1ci s hork\u00fdm sklem v huti\" />\n        </div>\n      </div>\n      <div class=\"container hero-buttons-row\">\n        <a href=\"#kontakt\" class=\"btn btn-primary\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n        <a href=\"#realizace\" class=\"btn btn-secondary\">POD\u00cdVAT SE, JAK SE PRACUJE SE SKLEM</a>\n      </div>\n    </section>\n\n    <!-- Section 2: UVP -->\n    <section id=\"uvp\" class=\"uvp-section container\">\n      <div class=\"section-title\">\n        <p class=\"eyebrow\">Pro\u010d toto u\u010dednictv\u00ed?</p>\n        <h2>SKUTE\u010cN\u00c9 \u0158EMESLO. SKUTE\u010cN\u00dd MISTR. SKUTE\u010cN\u00c1 PR\u00c1CE.</h2>\n        <p>Zjisti, pro\u010d je u\u010dednictv\u00ed v huti v\u00fdjime\u010dnou p\u0159\u00edle\u017eitost\u00ed oproti b\u011b\u017en\u00e9 \u0161kole nebo teoretick\u00fdm kurz\u016fm.</p>\n      </div>\n\n      <div class=\"uvp-grid\">\n        <div class=\"uvp-card\">\n          <h3>Osobn\u00ed veden\u00ed</h3>\n          <p>U\u010dedn\u00edk nen\u00ed anonymn\u00ed student v p\u0159epln\u011bn\u00e9 t\u0159\u00edd\u011b. U\u010d\u00ed\u0161 se p\u0159\u00edmo od Ji\u0159\u00edho a jeho t\u00fdmu v komorn\u00edm prost\u0159ed\u00ed.</p>\n        </div>\n        <div class=\"uvp-card\">\n          <h3>U\u010den\u00ed p\u0159\u00edmo v d\u00edln\u011b</h3>\n          <p>\u017d\u00e1dn\u00e9 hodiny sezen\u00ed nad u\u010debnicemi. Od prvn\u00edho dne pozn\u00e1v\u00e1\u0161 \u017e\u00e1r pece, pr\u00e1ci s p\u00ed\u0161\u0165alou a hork\u00fdm sklem.</p>\n        </div>\n        <div class=\"uvp-card\">\n          <h3>\u0158emeslo od z\u00e1klad\u016f</h3>\n          <p>Postupn\u00fd rozvoj dovednost\u00ed \u2013 od bezpe\u010dnosti a spr\u00e1vn\u00e9ho dr\u017een\u00ed n\u00e1stroj\u016f a\u017e po vlastn\u00ed tvarov\u00e1n\u00ed.</p>\n        </div>\n        <div class=\"uvp-card\">\n          <h3>Kontakt s re\u00e1lnou v\u00fdrobou</h3>\n          <p>Vid\u00ed\u0161, jak vznik\u00e1 profesion\u00e1ln\u00ed zak\u00e1zkov\u00e1 tvorba pro klienty a sb\u011bratele z cel\u00e9ho sv\u011bta.</p>\n                <div class=\"uvp-card\">\n          <h3>Mo\u017enost profesn\u00ed cesty</h3>\n          <p>C\u00edlem nen\u00ed si sklo jen zkusit, ale zjistit, zda se z ru\u010dn\u00edho \u0159emesla m\u016f\u017ee st\u00e1t tvoje budoucnost.</p>\n        </div>\n      </div>\n      <div class=\"section-cta-wrap\">\n        <a href=\"#kontakt\" class=\"btn btn-primary\" onclick=\"openLeadModal(event)\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n      </div>\n    </section>\n\n    <!-- Section 3: Authority / Mistr -->\n    <section id=\"mistr\" class=\"master-section\">\n      <div class=\"container master-grid\">\n        <div class=\"master-photo\">\n          <img src=\"../../images/sample_master.png\" alt=\"Mistr Ji\u0159\u00ed Pa\u010dinek\" />\n        </div>\n        <div class=\"master-info\">\n          <p class=\"eyebrow\">KDO T\u011a BUDE U\u010cIT</p>\n          <h3>JI\u0158\u00cd PA\u010cINEK</h3>\n          <p class=\"master-title\">Um\u011bleck\u00fd skl\u00e1\u0159 a mistr \u0159emesla \u2022 Skl\u00e1rna Kunratice u Cvikova</p>\n          <p>Ji\u0159\u00ed Pa\u010dinek vybudoval rodinnou skl\u00e1rnu Pa\u010dinek Glass a unik\u00e1tn\u00ed K\u0159i\u0161\u0165\u00e1lovou zahradu v Kunratic\u00edch u Cvikova. Jeho ru\u010dn\u011b tvarovan\u00e9 objekty, plastiky a sv\u00edtidla obdivuj\u00ed sb\u011bratel\u00e9 po cel\u00e9m sv\u011bt\u011b.</p>\n          <div class=\"quote-box\">\n            \u201e\u0158emeslo nen\u00ed jen pr\u00e1ce s materi\u00e1lem. Je to pokora, soust\u0159ed\u011bn\u00ed a schopnost vtisknout \u017ehav\u00e9 hmot\u011b tvar i my\u0161lenku.\u201c\n          </div>\n          <p>V d\u00edln\u011b s\u00e1z\u00ed na poctiv\u00fd p\u0159\u00edstup, t\u00fdmovou spolupr\u00e1ci u pece a p\u0159ed\u00e1v\u00e1n\u00ed skl\u00e1\u0159sk\u00e9ho um\u011bn\u00ed dal\u0161\u00ed generaci.</p>\n        </div>\n      </div>\n      <div class=\"container\">\n        <div class=\"section-cta-wrap\">\n          <a href=\"#kontakt\" class=\"btn btn-primary\" onclick=\"openLeadModal(event)\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n        </div>\n      </div>\n    </section>\n\n    <!-- Section 4: Learning Outcomes -->\n    <section id=\"co-se-naucis\" class=\"outcomes-section container\">\n      <div class=\"section-title\">\n        <p class=\"eyebrow\">Praktick\u00e9 dovednosti</p>\n        <h2>CO SE U\u010cEDN\u00cdK SKUTE\u010cN\u011a NAU\u010c\u00cd</h2>\n        <p>Konkr\u00e9tn\u00ed znalosti a n\u00e1vyky, kter\u00e9 si z d\u00edlny odnese\u0161 do \u017eivota.</p>\n      </div>\n\n      <div class=\"outcomes-grid\">\n        <div class=\"outcome-item\">\n          <h4>\ud83d\udd25 Pr\u00e1ce s n\u00e1stroji</h4>\n          <p>Pozn\u00e1\u0161 skl\u00e1\u0159skou p\u00ed\u0161\u0165alu, n\u016f\u017eky, sval\u00e1ky i kle\u0161t\u011b a nau\u010d\u00ed\u0161 se s nimi bezpe\u010dn\u011b manipulovat.</p>\n        </div>\n        <div class=\"outcome-item\">\n          <h4>\ud83e\uddea Pr\u00e1ce se sklem</h4>\n          <p>Pochop\u00ed\u0161 chov\u00e1n\u00ed roztaven\u00e9ho materi\u00e1lu p\u0159i teplot\u00e1ch p\u0159es 1100 \u00b0C a jeho chladnut\u00ed.</p>\n        </div>\n        <div class=\"outcome-item\">\n          <h4>\ud83c\udfa8 Tvarov\u00e1n\u00ed & Barvy</h4>\n          <p>Osvoj\u00ed\u0161 si z\u00e1klady fouk\u00e1n\u00ed, nav\u00edjen\u00ed barvy a formov\u00e1n\u00ed tvar\u016f u s\u00e1zec\u00ed pece.</p>\n        </div>\n        <div class=\"outcome-item\">\n          <h4>\ud83c\udfed Pr\u00e1ce v huti</h4>\n          <p>Za\u017eije\u0161 re\u00e1ln\u00fd rytmus t\u00fdmu na skl\u00e1\u0159sk\u00e9 huti a komunikaci p\u0159i spole\u010dn\u00e9m d\u00edle.</p>\n        </div>\n        <div class=\"outcome-item\">\n          <h4>\ud83d\udee1\ufe0f Bezpe\u010dnost & N\u00e1vyky</h4>\n          <p>Z\u00edsk\u00e1\u0161 respekt k hork\u00e9mu prost\u0159ed\u00ed a nau\u010d\u00ed\u0161 se p\u0159\u00edsn\u00fdm pravidl\u016fm ochrany zdrav\u00ed.</p>\n        </div>\n        <div class=\"outcome-item\">\n          <h4>\ud83d\udcaa Samostatnost & Trp\u011blivost</h4>\n          <p>Rozvine\u0161 soust\u0159ed\u011bn\u00ed, vytrvalost a schopnost u\u010dit se z vlastn\u00edch chyb.</p>\n        </div>\n      </div>\n      <div class=\"section-cta-wrap\">\n        <a href=\"#kontakt\" class=\"btn btn-primary\" onclick=\"openLeadModal(event)\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n      </div>\n    </section>\n\n    <!-- Section 5: How It Works -->\n    <section id=\"jak-to-probiha\" class=\"timeline-section\">\n      <div class=\"container\">\n        <div class=\"section-title\">\n          <p class=\"eyebrow\">Postup krok za krokem</p>\n          <h2>JAK PROB\u00cdH\u00c1 CESTA K U\u010cEDNICTV\u00cd</h2>\n          <p>P\u011bt jasn\u00fdch krok\u016f od prvn\u00edho projeven\u00ed z\u00e1jmu a\u017e po za\u010d\u00e1tek pr\u00e1ce v d\u00edln\u011b.</p>\n        </div>\n\n        <div class=\"timeline\">\n          <div class=\"timeline-step\">\n            <div class=\"step-number\">01</div>\n            <div class=\"step-content\">\n              <h4>PRVN\u00cd ROZHOVOR</h4>\n              <p>Nez\u00e1vazn\u00fd rozhovor se z\u00e1stupcem Svobodn\u00fdch cech\u016f (telefon/WhatsApp), kde zjist\u00edme tv\u00e1 o\u010dek\u00e1v\u00e1n\u00ed a zodpov\u00edme prvn\u00ed dotazy.</p>\n            </div>\n          </div>\n          <div class=\"timeline-step\">\n            <div class=\"step-number\">02</div>\n            <div class=\"step-content\">\n              <h4>SETK\u00c1N\u00cd S MISTREM</h4>\n              <p>Nav\u0161t\u00edv\u00ed\u0161 skl\u00e1rnu Pa\u010dinek Glass v Kunratic\u00edch u Cvikova, potk\u00e1\u0161 se s Ji\u0159\u00edm Pa\u010dinkem a prohl\u00e9dne\u0161 si hu\u0165.</p>\n            </div>\n          </div>\n          <div class=\"timeline-step\">\n            <div class=\"step-number\">03</div>\n            <div class=\"step-content\">\n              <h4>ZKU\u0160EBN\u00cd DEN</h4>\n              <p>Vyzkou\u0161\u00ed\u0161 si re\u00e1ln\u00fd den v d\u00edln\u011b. Ob\u011b strany si ov\u011b\u0159\u00ed, zda jim vz\u00e1jemn\u00e1 spolupr\u00e1ce a atmosf\u00e9ra vyhovuje.</p>\n            </div>\n          </div>\n          <div class=\"timeline-step\">\n            <div class=\"step-number\">04</div>\n            <div class=\"step-content\">\n              <h4>DOMLUV\u00cdME SE</h4>\n              <p>Spole\u010dn\u011b dohodneme konkr\u00e9tn\u00ed podm\u00ednky, \u010dasov\u00fd rozvrh, v\u011bkov\u00e9 a praktick\u00e9 mo\u017enosti (v\u010detn\u011b p\u0159\u00edpadn\u00e9ho ubytov\u00e1n\u00ed/strava).</p>\n            </div>\n          </div>\n          <div class=\"timeline-step\">\n            <div class=\"step-number\">05</div>\n            <div class=\"step-content\">\n              <h4>ZA\u010c\u00cdN\u00c1 U\u010cEDNICTV\u00cd</h4>\n              <p>Teprve po oboustrann\u00e9 dohod\u011b za\u010d\u00edn\u00e1 tvoje pravideln\u00e1 \u0159emesln\u00e1 cesta p\u0159\u00edmo u skl\u00e1\u0159sk\u00e9 pece.</p>\n            </div>\n          </div>\n        </div>\n\n        <p class=\"disclaimer-box\">\ud83d\udca1 Z\u00e1kladn\u00ed cesta vypad\u00e1 takto. Konkr\u00e9tn\u00ed pr\u016fb\u011bh se v\u017edy p\u0159izp\u016fsobuje \u010dlov\u011bku, jeho \u010dasov\u00fdm mo\u017enostem a zku\u0161enostem.</p>\n        <div class=\"section-cta-wrap\">\n          <a href=\"#kontakt\" class=\"btn btn-primary\" onclick=\"openLeadModal(event)\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n        </div>\n      </div>\n    </section>\n\n    <!-- Section 6: Portfolio -->\n    <section id=\"realizace\" class=\"portfolio-section container\">\n      <div class=\"section-title\">\n        <p class=\"eyebrow\">Uk\u00e1zka z prost\u0159ed\u00ed</p>\n        <h2>CO VZNIK\u00c1 V D\u00cdLN\u011a</h2>\n        <p>Nahl\u00e9dni do \u017eiv\u00e9ho procesu skl\u00e1\u0159sk\u00e9ho um\u011bn\u00ed \u2013 od materi\u00e1lu po hotov\u00e9 d\u00edlo.</p>\n      </div>\n\n      <div class=\"portfolio-grid\">\n        <div class=\"portfolio-item\">\n          <img src=\"../../images/sample_master.png\" alt=\"Pr\u00e1ce se sklovinou\" />\n          <div class=\"portfolio-caption\">\u017dhav\u00e1 sklovina u s\u00e1zec\u00ed pece</div>\n        </div>\n        <div class=\"portfolio-item\">\n          <img src=\"../../images/sample_master.png\" alt=\"Fouk\u00e1n\u00ed a tvarov\u00e1n\u00ed\" />\n          <div class=\"portfolio-caption\">Tvarov\u00e1n\u00ed na skl\u00e1\u0159sk\u00e9 lavici</div>\n        </div>\n        <div class=\"portfolio-item\">\n          <img src=\"../../images/sample_master.png\" alt=\"Detail objektu\" />\n          <div class=\"portfolio-caption\">Detail hutn\u011b tvarovan\u00e9 sklen\u011bn\u00e9 plastiky</div>\n        </div>\n        <div class=\"portfolio-item\">\n          <img src=\"../../images/sample_master.png\" alt=\"K\u0159i\u0161\u0165\u00e1lov\u00e1 zahrada\" />\n          <div class=\"portfolio-caption\">K\u0159i\u0161\u0165\u00e1lov\u00e1 zahrada v Kunratic\u00edch</div>\n        </div>\n      </div>\n      <div class=\"section-cta-wrap\">\n        <a href=\"#kontakt\" class=\"btn btn-primary\" onclick=\"openLeadModal(event)\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n      </div>\n    </section>\n\n    <!-- Section 7: Social Proof / Reference -->\n    <section id=\"reference\" class=\"testimonials-section\">\n      <div class=\"container\">\n        <div class=\"section-title\">\n          <p class=\"eyebrow\">Zku\u0161enosti a reference</p>\n          <h2>CO \u0158\u00cdKAJ\u00cd LID\u00c9, KTE\u0158\u00cd U TOHO BYLI</h2>\n          <p>Re\u00e1ln\u00e9 pohledy z\u00e1stupc\u016f, rodin a spolupracovn\u00edk\u016f.</p>\n        </div>\n\n        <div class=\"testimonials-grid\">\n          <div class=\"testimonial-card\">\n            <p class=\"quote-text\">\u201eSkl\u00e1\u0159stv\u00ed je tvrd\u00e1 pr\u00e1ce, ale vid\u011bt syna, jak pod veden\u00edm Ji\u0159\u00edho z\u00edsk\u00e1v\u00e1 jistotu a respekt k materi\u00e1lu, je neuv\u011b\u0159iteln\u00e9.\u201c</p>\n            <div class=\"author-info\">\n              <div>\n                <strong>Petr M.</strong>\n                <span>Rodi\u010d z\u00e1jemce o \u0159emeslo</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"testimonial-card\">\n            <p class=\"quote-text\">\u201eMo\u017enost stoupnout si k peci v Kunratic\u00edch a sledovat mistra Pa\u010dinka p\u0159i pr\u00e1ci mi otev\u0159ela o\u010di. \u0158emeslo m\u00e1 obrovskou budoucnost.\u201c</p>\n            <div class=\"author-info\">\n              <div>\n                <strong>Martin K.</strong>\n                <span>\u00da\u010dastn\u00edk zku\u0161ebn\u00edho dne</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"testimonial-card\">\n            <p class=\"quote-text\">\u201eSpolupr\u00e1ce se Svobodn\u00fdmi Cechy pom\u00e1h\u00e1 p\u0159iv\u00e9st k poctiv\u00fdm \u0159emesl\u016fm mlad\u00e9 lidi, kte\u0159\u00ed maj\u00ed chu\u0165 n\u011bco vytvo\u0159it vlastn\u00edma rukama.\u201c</p>\n            <div class=\"author-info\">\n              <div>\n                <strong>T\u00fdm Pa\u010dinek Glass</strong>\n                <span>Kunratice u Cvikova</span>\n              </div>\n            </div>\n          </div>\n        </div>\n        <div class=\"section-cta-wrap\">\n          <a href=\"#kontakt\" class=\"btn btn-primary\" onclick=\"openLeadModal(event)\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n        </div>\n      </div>\n    </section>\n\n    <!-- Section 8: FAQ -->\n    <section id=\"faq\" class=\"faq-section container\">\n      <div class=\"section-title\">\n        <p class=\"eyebrow\">Odpov\u011bdi na dotazy</p>\n        <h2>\u010cAST\u00c9 OT\u00c1ZKY</h2>\n        <p>V\u0161e, co t\u011b (nebo tvoje rodi\u010de) m\u016f\u017ee zaj\u00edmat p\u0159ed prvn\u00edm kontaktem.</p>\n      </div>\n\n      <div class=\"faq-list\">\n        <details>\n          <summary>Pro koho je u\u010dednictv\u00ed ur\u010deno?</summary>\n          <p>Prvo\u0159ad\u011b pro mlad\u00e9 lidi ve v\u011bku cca 12\u201318 let a mlad\u00e9 dosp\u011bl\u00e9, kte\u0159\u00ed maj\u00ed z\u00e1jem o ru\u010dn\u00ed \u0159emeslo, sklo a praktickou tvorbu.</p>\n        </details>\n        <details>\n          <summary>Mus\u00edm m\u00edt p\u0159edchoz\u00ed zku\u0161enosti se sklem?</summary>\n          <p>Nen\u00ed to nutn\u00e9! V\u0161echny z\u00e1klady bezpe\u010dnosti, manipulace s n\u00e1\u0159ad\u00edm i pr\u00e1ce s materi\u00e1lem t\u011b nau\u010d\u00edme p\u0159\u00edmo v d\u00edln\u011b.</p>\n        </details>\n        <details>\n          <summary>Jak prob\u00edh\u00e1 zku\u0161ebn\u00ed den?</summary>\n          <p>B\u011bhem zku\u0161ebn\u00edho dne se sezn\u00e1m\u00ed\u0161 s chodem huti, vyzkou\u0161\u00ed\u0161 si z\u00e1kladn\u00ed \u00fakony a zjist\u00ed\u0161, zda ti atmosf\u00e9ra v d\u00edln\u011b sed\u00ed.</p>\n        </details>\n        <details>\n          <summary>Kde p\u0159esn\u011b se u\u010dednictv\u00ed kon\u00e1?</summary>\n          <p>U\u010dednictv\u00ed prob\u00edh\u00e1 p\u0159\u00edmo v are\u00e1lu skl\u00e1rny Pa\u010dinek Glass v Kunratic\u00edch u Cvikova (Libereck\u00fd kraj).</p>\n        </details>\n        <details>\n          <summary>Je mo\u017en\u00e9 domluvit ubytov\u00e1n\u00ed, pokud jsem zdaleka?</summary>\n          <p>Mo\u017enosti ubytov\u00e1n\u00ed a dopravy \u0159e\u0161\u00edme individu\u00e1ln\u011b p\u0159i osobn\u00edm rozhovoru podle konkr\u00e9tn\u00edch pot\u0159eb u\u010dedn\u00edka.</p>\n        </details>\n        <details>\n          <summary>Mus\u00edm se hned k ne\u010demu zav\u00e1zat?</summary>\n          <p>V\u016fbec ne. Prvn\u00edm krokem je zcela nez\u00e1vazn\u00fd rozhovor, kde si vyjasn\u00edme dotazy a p\u0159edstav\u00edme mo\u017enosti.</p>\n        </details>\n      </div>\n      <div class=\"section-cta-wrap\">\n        <a href=\"#kontakt\" class=\"btn btn-primary\" onclick=\"openLeadModal(event)\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n      </div>\n    </section>\n\n    <!-- Section 9: Primary CTA -->\n    <div class=\"container\">\n      <div class=\"primary-cta-box\">\n        <h2>ZAJ\u00cdM\u00c1 T\u011a, JESTLI JE TO PRO TEBE?</h2>\n        <p>Nemus\u00ed\u0161 se hned k ni\u010demu zavazovat. Prvn\u00ed krok je jednoduch\u00fd nez\u00e1vazn\u00fd rozhovor, kde spole\u010dn\u011b probereme, co hled\u00e1\u0161 a jestli by ti u\u010dednictv\u00ed vyhovovalo.</p>\n        <a href=\"#kontakt\" class=\"btn btn-primary\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n      </div>\n    </div>\n\n    <!-- Section 10: Contact / Lead Capture -->\n    <section id=\"kontakt\" class=\"contact-section container\">\n      <div class=\"section-title\">\n        <p class=\"eyebrow\">Prvn\u00ed krok</p>\n        <h2>NAV\u00c1\u017dEME KONTAKT</h2>\n        <p>Zvol si zp\u016fsob, kter\u00fd je pro t\u011b nejsnadn\u011bj\u0161\u00ed.</p>\n      </div>\n\n      <div class=\"contact-grid\">\n        <!-- Variant A: Youth / Quick Contact -->\n        <div class=\"contact-card\">\n          <h3>\ud83d\udcac Rychl\u00e1 zpr\u00e1va (pro z\u00e1jemce)</h3>\n          <p>Nejrychlej\u0161\u00ed cesta je napsat n\u00e1m p\u0159\u00edmo na WhatsApp nebo Instagram. Zpr\u00e1va je p\u0159edvypln\u011bn\u00e1, sta\u010d\u00ed odeslat.</p>\n          \n          <div class=\"contact-options\">\n            <a href=\"https://wa.me/420602763599?text=Dobr%C3%BD%20den,%20cht%C4%9Bl/a%20bych%20zjistit,%20jestli%20je%20u%C4%8Dednictv%C3%AD%20u%20Ji%C5%99%C3%ADho%20Pa%C4%8Dinka%20pro%20m%C4%9B.\" class=\"btn-wa\" target=\"_blank\">\n              NAPSAT NA WHATSAPP (+420 602 763 599)\n            </a>\n            <a href=\"https://instagram.com\" class=\"btn-ig\" target=\"_blank\">\n              NAPSAT NA INSTAGRAM\n            </a>\n          </div>\n\n          <div class=\"parent-box\">\n            <h4 style=\"font-family: var(--font-heading); font-size: 1.4rem; color: var(--color-white); margin-bottom: 0.5rem;\">\ud83d\udc68\u200d\ud83d\udc69\u200d\ud83d\udc66 Jste rodi\u010d?</h4>\n            <p style=\"font-size: 0.95rem; color: var(--text-muted);\">Pokud se pt\u00e1te za sv\u00e9ho syna nebo dceru, r\u00e1di v\u00e1m v\u0161e podrobn\u011b vysv\u011btl\u00edme telefonicky nebo e-mailem.</p>\n            <a href=\"tel:+420602763599\" class=\"btn btn-secondary\" style=\"margin-top: 1rem; width: 100%;\">CHCI SI ZAVOLAT (+420 602 763 599)</a>\n          </div>\n        </div>\n\n        <!-- Form option -->\n        <div class=\"contact-card\">\n          <h3>\ud83d\udcdd Kontaktn\u00ed formul\u00e1\u0159</h3>\n          <form id=\"lead-form\" onsubmit=\"event.preventDefault(); alert('D\u011bkujeme za zpr\u00e1vu! Va\u0161i popt\u00e1vku jsme p\u0159ijali a brzy se v\u00e1m ozveme.');\">\n            <div class=\"form-group\">\n              <label for=\"form-name\">Tvoje jm\u00e9no / Jm\u00e9no rodi\u010de</label>\n              <input type=\"text\" id=\"form-name\" class=\"form-control\" placeholder=\"Jan Nov\u00e1k\" required />\n            </div>\n            \n            <div class=\"form-group\">\n              <label for=\"form-role\">Jsem:</label>\n              <select id=\"form-role\" class=\"form-control\" required>\n                <option value=\"student\">Budouc\u00ed u\u010dedn\u00edk</option>\n                <option value=\"parent\">Rodi\u010d z\u00e1jemce</option>\n                <option value=\"other\">Jin\u00fd z\u00e1jemce</option>\n              </select>\n            </div>\n\n            <div class=\"form-group\">\n              <label for=\"form-contact\">Telefon / WhatsApp / E-mail</label>\n              <input type=\"text\" id=\"form-contact\" class=\"form-control\" placeholder=\"+420 ... nebo email@seznam.cz\" required />\n            </div>\n\n            <div class=\"form-group\">\n              <label for=\"form-note\">Co t\u011b na u\u010dednictv\u00ed zaj\u00edm\u00e1? (dobrovoln\u00e9)</label>\n              <textarea id=\"form-note\" class=\"form-control\" rows=\"3\" placeholder=\"Chci se zeptat na...\"></textarea>\n            </div>\n\n            <button type=\"submit\" class=\"btn btn-primary\" style=\"width: 100%;\">ODESLAT DOTAZ</button>\n            <p style=\"font-size: 0.78rem; color: var(--text-muted); margin-top: 0.8rem; text-align: center;\">Odesl\u00e1n\u00edm formul\u00e1\u0159e berete na v\u011bdom\u00ed <a href=\"../../zasady-ochrany-osobnich-udaju.html\" target=\"_blank\" style=\"color:var(--color-accent, #e87516); text-decoration:underline;\">zpracov\u00e1n\u00ed osobn\u00edch \u00fadaj\u016f</a> pro \u00fa\u010dely vy\u0159\u00edzen\u00ed va\u0161eho dotazu.</p>\n          </form>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <!-- Sticky Mobile CTA Bar -->\n  <div class=\"mobile-sticky-cta\">\n    <a href=\"#kontakt\" class=\"btn btn-primary\">ZJISTIT, JESTLI JE TO PRO M\u011a</a>\n  </div>\n\n  <footer>\n    <div class=\"container\">\n      <p>\u00a9 2026 Pa\u010dinek Glass & Svobodn\u00e9 Cechy. V\u0161echna pr\u00e1va vyhrazena.</p>\n      <p style=\"margin-top: 0.5rem; font-size: 0.8rem;\">Soukrom\u00e1 str\u00e1nka pro n\u00e1borovou kampa\u0148 u\u010dednictv\u00ed.</p>\n    </div>\n  <!-- LEAD CAPTURE POPUP MODAL (3 PHASES) -->\n  <div id=\"leadModal\" class=\"lead-modal-overlay\">\n    <div class=\"lead-modal-box\">\n      <button type=\"button\" class=\"lead-modal-close\" onclick=\"closeLeadModal()\">&times;</button>\n      \n      <!-- STEP 1: EMAIL CAPTURE -->\n      <div id=\"modalStep1\" class=\"modal-step\">\n        <h3>Zanechte n\u00e1m sv\u016fj e-mail</h3>\n        <p>Za\u0161leme v\u00e1m podrobn\u00e9 informace o u\u010dednictv\u00ed a propoj\u00edme v\u00e1s s mistrem.</p>\n        <form onsubmit=\"submitStep1(event)\">\n          <div class=\"form-group\">\n            <label style=\"display:block; font-size:0.85rem; margin-bottom:0.3rem; color:var(--color-accent); font-weight:700;\">V\u00e1\u0161 E-mail *</label>\n            <input type=\"email\" id=\"m_email\" name=\"email\" autocomplete=\"email\" class=\"form-control\" placeholder=\"nap\u0159. jan.novak@seznam.cz\" required />\n          </div>\n          <button type=\"submit\" id=\"m_s1_submit_btn\" class=\"btn btn-primary\" style=\"width:100%; margin-top:0.5rem;\">POKRA\u010cOVAT</button>\n          <div class=\"gdpr-notice\" style=\"margin-top:0.8rem; font-size:0.78rem; color:var(--text-muted, #94a3b8); text-align:center; line-height:1.4;\">\n            Odesl\u00e1n\u00edm e-mailu berete na v\u011bdom\u00ed <a href=\"../../zasady-ochrany-osobnich-udaju.html\" target=\"_blank\" style=\"color:var(--color-accent, #e87516); text-decoration:underline;\">zpracov\u00e1n\u00ed osobn\u00edch \u00fadaj\u016f</a> pro \u00fa\u010dely zasl\u00e1n\u00ed informac\u00ed o u\u010dednictv\u00ed a navazuj\u00edc\u00ed komunikaci.\n          </div>\n        </form>\n      </div>\n\n      <!-- STEP 2: ADDITIONAL DETAILS & WHATSAPP -->\n      <div id=\"modalStep2\" class=\"modal-step\" style=\"display:none;\">\n        <h3>Dopl\u0148uj\u00edc\u00ed \u00fadaje (voliteln\u00e9)</h3>\n        <p>Chcete-li, abychom v\u00e1m p\u0159\u00edmo zavolali nebo poslali zpr\u00e1vu, vypl\u0148te va\u0161e jm\u00e9no a telefon.</p>\n        <form onsubmit=\"submitStep2(event)\">\n          <div class=\"form-group\">\n            <label style=\"display:block; font-size:0.85rem; margin-bottom:0.3rem; color:var(--color-accent); font-weight:700;\">Jm\u00e9no a p\u0159\u00edjmen\u00ed</label>\n            <input type=\"text\" id=\"m_name\" name=\"name\" autocomplete=\"name\" class=\"form-control\" placeholder=\"Jan Nov\u00e1k\" />\n          </div>\n          <div class=\"form-group\">\n            <label style=\"display:block; font-size:0.85rem; margin-bottom:0.3rem; color:var(--color-accent); font-weight:700;\">Telefon</label>\n            <input type=\"tel\" id=\"m_phone\" name=\"phone\" autocomplete=\"tel\" class=\"form-control\" placeholder=\"+420 602 123 456\" />\n          </div>\n          <div class=\"form-group\">\n            <label style=\"display:block; font-size:0.85rem; margin-bottom:0.3rem; color:var(--color-accent); font-weight:700;\">Jsem:</label>\n            <select id=\"m_role\" class=\"form-control\">\n              <option value=\"Budouc\u00ed u\u010dedn\u00edk\">Budouc\u00ed u\u010dedn\u00edk</option>\n              <option value=\"Rodi\u010d\">Rodi\u010d</option>\n            </select>\n          </div>\n          <div class=\"form-group\">\n            <label style=\"display:block; font-size:0.85rem; margin-bottom:0.3rem; color:var(--color-accent); font-weight:700;\">Zpr\u00e1va nebo dotaz (voliteln\u00e9)</label>\n            <textarea id=\"m_msg\" class=\"form-control\" placeholder=\"M\u00e1m z\u00e1jem o bli\u017e\u0161\u00ed informace...\"></textarea>\n          </div>\n          <button type=\"submit\" id=\"m_s2_submit_btn\" class=\"btn btn-primary\" style=\"width:100%; margin-top:0.5rem;\">ODESLAT V\u0160ECHNO</button>\n          <div class=\"gdpr-notice\" style=\"margin-top:0.8rem; font-size:0.78rem; color:var(--text-muted, #94a3b8); text-align:center; line-height:1.4;\">\n            Odesl\u00e1n\u00edm formul\u00e1\u0159e berete na v\u011bdom\u00ed <a href=\"../../zasady-ochrany-osobnich-udaju.html\" target=\"_blank\" style=\"color:var(--color-accent, #e87516); text-decoration:underline;\">zpracov\u00e1n\u00ed osobn\u00edch \u00fadaj\u016f</a> pro \u00fa\u010dely vy\u0159\u00edzen\u00ed va\u0161eho dotazu.\n          </div>\n          <div class=\"newsletter-option\" style=\"margin-top:0.6rem; text-align:left; font-size:0.82rem; color:var(--text-muted, #cbd5e1); display:flex; align-items:flex-start; gap:0.5rem;\">\n            <input type=\"checkbox\" id=\"m_newsletter\" name=\"newsletter\" style=\"accent-color:var(--color-accent, #e87516); width:16px; height:16px; margin-top:2px; cursor:pointer;\" />\n            <label for=\"m_newsletter\" style=\"cursor:pointer; margin:0; line-height:1.3;\">Chci dost\u00e1vat novinky a pravideln\u00fd newsletter od Svobodn\u00e9 Cechy.</label>\n          </div>\n        </form>\n        <div style=\"text-align:center; margin-top:1rem; padding-top:1rem; border-top:1px solid var(--color-glass-border);\">\n          <button type=\"button\" onclick=\"submitStep2AndWhatsApp(event, 'https://wa.me/420602763599?text=Dobr%C3%BD%20den,%20cht%C4%9Bl/a%20bych%20zjistit,%20jestli%20je%20u%C4%8Dednictv%C3%AD%20u%20Ji%C5%99%C3%ADho%20Pa%C4%8Dinka%20pro%20m%C4%9B.')\" class=\"btn-wa\" style=\"width:100%; border:none; cursor:pointer;\">NAPSAT ROVNOU NA WHATSAPP</button>\n        </div>\n      </div>\n\n      <!-- STEP 3: THANK YOU -->\n      <div id=\"modalStep3\" class=\"modal-step\" style=\"display:none;\">\n        <h3>D\u011bkujeme za v\u00e1\u0161 z\u00e1jem!</h3>\n        <p id=\"m_s3_text_el\">Va\u0161i zpr\u00e1vu jsme v po\u0159\u00e1dku p\u0159ijali. Ozveme se v\u00e1m do 24 hodin.</p>\n        <button type=\"button\" id=\"m_s3_close_btn\" class=\"btn btn-primary\" onclick=\"closeLeadModal()\" style=\"width:100%; margin-top:1rem;\">ZAV\u0158\u00cdT</button>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    let currentLeadId = null;\n\n    function openLeadModal(e) {\n      if (e && e.preventDefault) e.preventDefault();\n      const modal = document.getElementById('leadModal');\n      if (modal) {\n        modal.style.display = 'flex';\n        const emailInput = document.getElementById('m_email');\n        if (emailInput) setTimeout(() => emailInput.focus(), 100);\n      }\n    }\n\n    function closeLeadModal() {\n      const modal = document.getElementById('leadModal');\n      if (modal) modal.style.display = 'none';\n    }\n\n    function submitStep1(e) {\n      e.preventDefault();\n      const btn = document.getElementById('m_s1_submit_btn');\n      if (btn) btn.disabled = true;\n\n      const email = document.getElementById('m_email').value;\n\n      fetch('../api_landing_leads.php?action=capture_email', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          email: email,\n          landing_slug: 'jiri-pacinek',\n          master_name: 'Ji\u0159\u00ed Pa\u010dinek'\n        })\n      })\n      .then(res => res.json())\n      .then(data => {\n        if (data.lead_id) currentLeadId = data.lead_id;\n        document.getElementById('modalStep1').style.display = 'none';\n        document.getElementById('modalStep2').style.display = 'block';\n      })\n      .catch(err => {\n        document.getElementById('modalStep1').style.display = 'none';\n        document.getElementById('modalStep2').style.display = 'block';\n      });\n    }\n\n    function submitStep2(e) {\n      e.preventDefault();\n      const btn = document.getElementById('m_s2_submit_btn');\n      if (btn) btn.disabled = true;\n\n      fetch('../api_landing_leads.php?action=update_lead', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          lead_id: currentLeadId,\n          email: document.getElementById('m_email').value,\n          landing_slug: 'jiri-pacinek',\n          name: document.getElementById('m_name').value,\n          phone: document.getElementById('m_phone').value,\n          user_role: document.getElementById('m_role').value,\n          message: document.getElementById('m_msg').value,\n          newsletter: document.getElementById('m_newsletter')?.checked ? 1 : 0\n        })\n      })\n      .then(res => res.json())\n      .then(data => {\n        document.getElementById('modalStep2').style.display = 'none';\n        document.getElementById('modalStep3').style.display = 'block';\n      })\n      .catch(err => {\n        document.getElementById('modalStep2').style.display = 'none';\n        document.getElementById('modalStep3').style.display = 'block';\n      });\n    }\n\n    function submitStep2AndWhatsApp(e, waUrl) {\n      if (e && e.preventDefault) e.preventDefault();\n\n      // Pre-open new tab to avoid popup blocker\n      const waWin = window.open('about:blank', '_blank');\n\n      const nameVal = document.getElementById('m_name').value.trim();\n      const msgVal = document.getElementById('m_msg').value.trim();\n\n      fetch('../api_landing_leads.php?action=update_lead', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          lead_id: currentLeadId,\n          email: document.getElementById('m_email').value,\n          landing_slug: 'jiri-pacinek',\n          name: nameVal,\n          phone: document.getElementById('m_phone').value,\n          user_role: document.getElementById('m_role').value,\n          message: msgVal,\n          newsletter: document.getElementById('m_newsletter')?.checked ? 1 : 0\n        })\n      })\n      .then(res => res.json())\n      .then(data => {\n        if (waWin) waWin.location.href = waUrl;\n        document.getElementById('modalStep2').style.display = 'none';\n        document.getElementById('modalStep3').style.display = 'block';\n      })\n      .catch(err => {\n        if (waWin) waWin.location.href = waUrl;\n        document.getElementById('modalStep2').style.display = 'none';\n        document.getElementById('modalStep3').style.display = 'block';\n      });\n    }\n  </script>\n</body>\n</html>\n";

$jsonOk = file_put_contents($dir . "/jiri-pacinek.json", $jsonContent);
